//! SQLite persistence layer for Komari.
//!
//! This crate is a drop-in replacement for the Go backend's `database`
//! packages. It reads and writes the schema generated by GORM so an existing
//! `data/komari.db` keeps working while the rest of the backend is rewritten.
//!
//! ```no_run
//! use komari_db::Db;
//!
//! # fn main() -> komari_db::Result<()> {
//! let db = Db::open("data/komari.db")?;
//! db.migrate()?;
//! # Ok(())
//! # }
//! ```

pub mod error;
pub mod json;
pub mod models;
pub mod time;
pub mod util;

pub use error::{DbError, Result};
pub use json::StringArray;
pub use time::LocalTime;
